    "code": "import asyncio
import aiohttp
import json
from datetime import datetime

async def setup():
    pass

async def process(mqtt_client, logger):
    pass

async def handle_task(mqtt_client, logger, task_queue):
    while True:
        try:
            message = await asyncio.wait_for(task_queue.get(), timeout=1.0)
            if message['topic'] == 'schedule/morning-weather-telegram/fired':
                # Fetch weather from weather-agent
                weather_data = await fetch_weather('home')
                if weather_data:
                    temp = weather_data.get('temp_c', 'N/A')
                    condition = weather_data.get('condition', 'Unknown')
                    message_text = f'Good morning! Today\'s weather: {temp}°C, {condition}'

                    # Send via telegram-notifier
                    await send_telegram(message_text, logger)
        except asyncio.TimeoutError:
            continue
        except Exception as e:
            logger.error(f'Error in weather-telegram-notifier: {e}')

async def fetch_weather(city):
    try:
        async with aiohttp.ClientSession() as session:
            async with session.get(f'https://wttr.in/{city}?format=j1') as resp:
                if resp.status == 200:
                    data = await resp.json()
                    current = data['current_condition'][0]
                    return {
                        'temp_c': current['temp_C'],
                        'condition': current['weatherDesc'][0]['value']
                    }
    except Exception:
        pass
    return None

async def send_telegram(text, logger):
    try:
        async with aiohttp.ClientSession() as session:
            payload = {'text': text}
            async with session.post('http://localhost:8123/api/telegram', json=payload) as resp:
                return resp.status == 200
    except Exception as e:
        logger.error(f'Failed to send Telegram: {e}')
    return False"
  }
