    "description": "Monitors office temperature stream and flags anomalies using statistical analysis",
    "poll_interval": 60,
    "code": "import json
import statistics
from collections import deque

class OfficeTemperatureAnomalyDetector:
    def __init__(self):
        self.temp_history = deque(maxlen=20)
        self.anomaly_threshold = 2.5

    async def setup(self):
        pass

    async def process(self, payload):
        try:
            temp = float(payload.get('temp'))
            self.temp_history.append(temp)

            if len(self.temp_history) < 5:
                return {'anomaly': False, 'score': 0.0, 'reason': 'insufficient_history'}

            mean_temp = statistics.mean(self.temp_history)
            stdev_temp = statistics.stdev(self.temp_history)

            if stdev_temp == 0:
                return {'anomaly': False, 'score': 0.0, 'reason': 'no_variance'}

            z_score = abs((temp - mean_temp) / stdev_temp)
            is_anomaly = z_score > self.anomaly_threshold

            return {
                'anomaly': is_anomaly,
                'score': z_score,
                'temp': temp,
                'mean': round(mean_temp, 2),
                'stdev': round(stdev_temp, 2),
                'reason': 'z_score_exceeded' if is_anomaly else 'normal'
            }
        except Exception as e:
            return {'anomaly': False, 'score': 0.0, 'error': str(e)}

