async def setup(agent):
    agent.state['hostname'] = agent.state.get('hostname', 'example.com')
    agent.declare_contract(
        publishes=['custom/host/dns'],
        subscribes=[]
    )
    await agent.log(f"DNS resolver agent initialized for host: {agent.state['hostname']}")


async def process(agent):
    import asyncio
    import socket

    hostname = agent.state.get('hostname', 'example.com')

    def resolve(host):
        try:
            return socket.gethostbyname(host)
        except socket.gaierror as e:
            return None

    loop = asyncio.get_event_loop()
    address = await loop.run_in_executor(None, resolve, hostname)

    if address:
        await agent.publish('custom/host/dns', {
            'hostname': hostname,
            'address': address
        })
        agent.state['last_address'] = address
    else:
        await agent.alert(f"Failed to resolve DNS for {hostname}", "warning")


async def cleanup(agent):
    await agent.log("DNS resolver agent shutting down")
