async def setup(agent):
    agent.declare_contract(
        publishes=["custom/host/wifi"],
        subscribes=[]
    )
    agent.state["initialized"] = True


async def process(agent):
    import asyncio

    def get_wifi_signal():
        import subprocess
        import platform
        import re

        system = platform.system()
        signal_strength = None

        try:
            if system == "Linux":
                output = subprocess.check_output(
                    ["iwconfig"], stderr=subprocess.DEVNULL
                ).decode(errors="ignore")
                match = re.search(r"Signal level=(-?\d+)", output)
                if match:
                    signal_strength = int(match.group(1))
                else:
                    proc_output = subprocess.check_output(
                        ["cat", "/proc/net/wireless"], stderr=subprocess.DEVNULL
                    ).decode(errors="ignore")
                    lines = proc_output.strip().split("\n")
                    if len(lines) >= 3:
                        parts = lines[2].split()
                        if len(parts) >= 4:
                            signal_strength = float(parts[3])

            elif system == "Darwin":
                output = subprocess.check_output(
                    ["airport", "-I"],
                    stderr=subprocess.DEVNULL
                ).decode(errors="ignore")
                match = re.search(r"agrCtlRSSI:\s*(-?\d+)", output)
                if match:
                    signal_strength = int(match.group(1))

            elif system == "Windows":
                output = subprocess.check_output(
                    ["netsh", "wlan", "show", "interfaces"],
                    stderr=subprocess.DEVNULL
                ).decode(errors="ignore")
                match = re.search(r"Signal\s*:\s*(\d+)%", output)
                if match:
                    signal_strength = int(match.group(1))

        except Exception:
            signal_strength = None

        return signal_strength

    loop = asyncio.get_event_loop()
    signal = await loop.run_in_executor(None, get_wifi_signal)

    payload = {
        "signal_strength": signal,
        "unit": "dBm_or_percent",
        "available": signal is not None
    }

    await agent.publish("custom/host/wifi", payload)

    if signal is None:
        await agent.log("Wi-Fi signal strength unavailable on this system")
    else:
        await agent.log(f"Published Wi-Fi signal strength: {signal}")


async def cleanup(agent):
    pass
```

