async def setup(agent):
    agent.declare_contract(
        publishes=['custom/home/energy_avg'],
        subscribes=['custom/home/energy']
    )
    agent.state['window'] = agent.window('custom/home/energy', seconds=60)


async def process(agent):
    window = agent.state.get('window')
    if window is None:
        window = agent.window('custom/home/energy', seconds=60)
        agent.state['window'] = window

    values = []
    try:
        data = window.data if hasattr(window, 'data') else list(window)
    except TypeError:
        data = []

    for item in data:
        val = None
        if isinstance(item, dict):
            val = item.get('value', item.get('energy'))
        elif isinstance(item, (int, float)):
            val = item
        elif isinstance(item, (tuple, list)) and len(item) >= 2:
            val = item[1]

        if isinstance(val, dict):
            val = val.get('value', val.get('energy'))

        if isinstance(val, (int, float)):
            values.append(val)

    if not values:
        return

    mean_val = sum(values) / len(values)

    await agent.publish('custom/home/energy_avg', {
        'mean': mean_val,
        'count': len(values),
        'window_seconds': 60
    })

    await agent.log(f"Published rolling mean: {mean_val:.2f} over {len(values)} samples")


async def cleanup(agent):
    pass
