import asyncio

async def setup(agent):
    agent.state.update({
        "model": None,
        "last_run": 0,
        "running": True
    })
    agent.declare_contract(
        publishes=["custom/camera/detections"],
        subscribes=["custom/camera/command"]
    )
    await agent.log("YOLO Agent Initialized")

async def handle_task(agent, payload):
    if payload.get("command") == "stop":
        agent.state["running"] = False
    elif payload.get("command") == "reset":
        agent.state["model"] = None

async def process(agent):
    if not agent.state["running"]:
        return

    # Lazy load model to avoid blocking setup
    if agent.state["model"] is None:
        from ultralytics import YOLO
        import cv2
        # Using a standard executor to prevent blocking the event loop during import/load
        def load_model():
            return YOLO("yolov8n.pt")

        agent.state["model"] = await asyncio.get_event_loop().run_in_executor(None, load_model)
        await agent.log("YOLO Model Loaded")

    import cv2
    import numpy as np

    def capture_and_detect(model):
        cap = cv2.VideoCapture(0)
        ret, frame = cap.read()
        cap.release()

        if not ret:
            return None

        results = model(frame, verbose=False)
        detections = []
        for r in results:
            for box in r.boxes:
                detections.append({
                    "class": str(r.names[int(box.cls)]),
                    "confidence": float(box.conf),
                    "bbox": box.xyxy.tolist()[0]
                })
        return detections

    try:
        # Run the heavy blocking CV/Inference task in an executor
        detections = await asyncio.get_event_loop().run_in_executor(
            None, 
            capture_and_detect, 
            agent.state["model"]
        )

        if detections is not None:
            await agent.publish("custom/camera/detections", {"detections": detections})
            if len(detections) > 0:
                await agent.log(f"Detected {len(detections)} objects")
        else:
            await agent.alert("Camera capture failed", "high")

    except Exception as e:
        await agent.alert(f"Inference Error: {str(e)}", "critical")

async def cleanup(agent):
    agent.state["running"] = False
    await agent.log("YOLO Agent Shutting Down")

import asyncio

async def setup(agent):
    agent.state.update({
        "target_host": None,
        "last_ip": None,
        "is_running": True
    })
    agent.declare_contract(
        publishes=["custom/host/dns"],
        subscribes=["custom/host/config"]
    )

async def handle_task(agent, payload):
    if isinstance(payload, dict) and "host" in payload:
        agent.state["target_host"] = payload["host"]
        await agent.log(f"Target host updated to: {payload['host']}")

async def process(agent):
    host = agent.state.get("target_host")
    if not host:
        return

    import socket

    def resolve():
        try:
            return socket.gethostbyname(host)
        except Exception as e:
            return None

    loop = asyncio.get_event_loop()
    current_ip = await loop.run_in_executor(None, resolve)

    if current_ip and current_ip != agent.state.get("last_ip"):
        agent.state["last_ip"] = current_ip
        await agent.publish("custom/host/dns", {"host": host, "ip": current_ip})
        await agent.log(f"DNS Resolved: {host} -> {current_ip}")
    elif not current_ip:
        await agent.alert(f"Failed to resolve host: {host}", "warning")

async def cleanup(agent):
    agent.state["is_running"] = False
    await agent.log("DNS Agent shutting down")

