async def process(agent):
    import psutil
    import subprocess
    import asyncio

    def get_wifi_rssi():
        try:
            # Platform specific implementation for Linux/macOS/Windows
            # This is a simplified placeholder for the logic
            import platform
            system = platform.system()
            if system == "Linux":
                cmd = ["nmcli", "-t", "-f", "IN-USE,SIGNAL", "dev", "wifi"]
                output = subprocess.check_output(cmd).decode()
                for line in output.split('\n'):
                    if line.startswith('*'):
                        return int(line.split('\t')[1])
            elif system == "Darwin":
                cmd = ["/System/Library/PrivateFrameworks/Apple80211.framework/Versions/Current/Resources/airport", "-I"]
                output = subprocess.check_output(cmd).decode()
                for line in output.split('\n'):
                    if "RSSI" in line:
                        return int(line.split(':')[1].strip())
            return -100
        except Exception:
            return -100

    loop = asyncio.get_event_loop()
    rssi = await loop.run_in_executor(None, get_wifi_rssi)

    if rssi != agent.state.get("last_rssi"):
        agent.state["last_rssi"] = rssi
        await agent.publish("custom/host/wifi", {"rssi": rssi})
        await agent.log(f"WiFi Signal Strength updated: {rssi} dBm")

