async def handle_task(agent, payload):
    pass

async def process(agent):
    try:
        value = await agent.mqtt_get("custom/office/climate")
        if value is not None:
            if agent.state["last_value"] != value:
                agent.state["last_value"] = value
                await agent.log(f"New climate reading: {value}")
            else:
                await agent.log("Climate reading unchanged.")
        else:
            await agent.log("No data available on custom/office/climate")
    except Exception as e:
        await agent.alert(f"Error reading climate: {str(e)}", "high")

async def cleanup(agent):
    pass

async def setup(agent):
    agent.declare_contract(
        publishes=["task/results"],
        subscribes=["task/requests"]
    )
    agent.state["last_error"] = None

async def handle_task(agent, payload):
    topic = payload.get("topic")
    if not topic:
        return {"error": "Missing topic in payload"}

    try:
        result = await agent.mqtt_get(topic)
        return {"result": result}
    except Exception as e:
        await agent.log(f"Error reading topic {topic}: {str(e)}")
        return {"error": str(e)}

async def process(agent):
    pass

async def cleanup(agent):
    await agent.log("Agent shutting down")

